285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
288	        Owner owner = this.clinicService.findOwnerById(ownerId);
289	        if (owner != null) {
290	            Pet pet = owner.getPet(petId);
291	            if (pet != null) {
292	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
293	            }
294	        }
295	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
296	    }
297	
298	    /**
299	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
300	     * offending field is collected so the caller learns exactly which values must be supplied.
301	     *
302	     * @param ownerFieldsDto the submitted owner payload
303	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
304	     *         telephone is missing or blank
305	     */
306	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
307	        List<String> missingFields = new ArrayList<>();
308	        if (isBlank(ownerFieldsDto.getFirstName())) {
309	            missingFields.add("firstName");
310	        }
311	        if (isBlank(ownerFieldsDto.getLastName())) {
312	            missingFields.add("lastName");
313	        }
314	        if (isBlank(ownerFieldsDto.getAddressLine1())
315	            && isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
316	            missingFields.add("address");
317	        }
318	        if (isBlank(ownerFieldsDto.getCity())) {
319	            missingFields.add("city");
320	        }
321	        if (isBlank(ownerFieldsDto.getTelephone())) {
322	            missingFields.add("telephone");
323	        }
324	        if (!missingFields.isEmpty()) {
325	            throw new MissingOwnerFieldsException(missingFields);
326	        }
327	    }
328	
329	    private boolean isBlank(String value) {
330	        return value == null || value.isBlank();
331	    }
332	
333	    /**
334	     * Rejects an owner create whose supplied {@code registrationDate} is later than the server's
335	     * current date. A registration date may not lie in the future; a value equal to today or in the
336	     * past is accepted, and an absent date is left to default to the server date.
337	     *
