439	    /**
440	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
441	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
442	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
443	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). Two owners resolve
444	     * to the same base code only when they share a region and produce the same telephone-and-last-name
445	     * hash; when the computed code collides with an existing owner's customer code it is de-duplicated
446	     * by appending '-&lt;n&gt;' with the smallest {@code n} of 2 or more that makes it unique.
447	     *
448	     * @param postcode the owner's postcode, used first to derive the region
449	     * @param city the owner's city, used to derive the region when the postcode maps to none
450	     * @param normalizedTelephone the owner's normalized (E.164) telephone
451	     * @param lastName the owner's last name
452	     * @return the formatted, de-duplicated customer code
453	     */
454	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
455	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
456	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
457	        String baseCode = region + "-" + hash8;
458	        return deduplicateCustomerCode(baseCode);
459	    }
