498	    /**
499	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
500	     * country calling code. Australia ('+61') uses 9 national digits and the North American
501	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
502	     * E.164 length (8 to 15 digits overall).
503	     */
504	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
505	        java.util.Map.of("61", 9, "1", 10);
506	
507	    /**
508	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
509	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
510	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
511	     * digits. The result must be a '+' followed by 8 to 15 digits, and its national number must have
512	     * the exact length its country code requires ('+61' needs 9 national digits, '+1' needs 10). This
513	     * E.164 string is what gets stored and returned.
514	     *
515	     * @param telephone the raw telephone value from the request
516	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
517	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number or its
518	     *         national number has the wrong length for its country code
519	     */
520	    private String normalizeTelephone(String telephone) {
521	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
522	        String e164;
523	        if (cleaned.startsWith("+")) {
524	            e164 = cleaned;
525	        } else {
526	            String national = cleaned;
527	            if (national.startsWith("0")) {
528	                national = national.substring(1);
529	            }
530	            e164 = "+61" + national;
531	        }
532	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
533	            throw new InvalidOwnerFieldsException(List.of("telephone"));
534	        }
535	        validateNationalNumberLength(e164);
536	        return e164;
537	    }
538	
539	    /**
540	     * Rejects an E.164 telephone whose national number does not have the exact length its country
541	     * calling code requires. The digits after the leading '+' are split into the longest matching
542	     * country code from {@link #NATIONAL_NUMBER_LENGTHS} and the remaining national number; when the
543	     * code is known and the national number's length differs from the required count the telephone is
544	     * rejected. Numbers whose country code is not listed are left to the generic E.164 length rule.
545	     *
546	     * @param e164 the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
547	     * @throws InvalidOwnerFieldsException if the national number has the wrong length for its country code
548	     */
549	    private void validateNationalNumberLength(String e164) {
550	        String digits = e164.substring(1);
551	        for (int codeLength = Math.min(3, digits.length()); codeLength >= 1; codeLength--) {
552	            String countryCode = digits.substring(0, codeLength);
553	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
554	            if (requiredNationalLength != null) {
555	                int nationalLength = digits.length() - codeLength;
556	                if (nationalLength != requiredNationalLength) {
557	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
558	                }
559	                return;
560	            }
561	        }
562	    }
