138	    /**
139	     * The known E.164 country calling codes this owner's telephone may carry, used only to split the
140	     * stored number into its country code and national digits for display. Australia ('+61') and the
141	     * North American Numbering Plan ('+1') mirror the codes the create endpoint recognises.
142	     */
143	    private static final String[] KNOWN_COUNTRY_CODES = {"61", "1"};
144	
145	    /**
146	     * The stored E.164 {@code telephone} formatted for human reading: the country calling code (kept
147	     * with its leading {@code '+'}), a space, then the national digits grouped in threes from the left
148	     * and separated by spaces (e.g. {@code +61412345678} becomes {@code "+61 412 345 678"}). The
149	     * country code is taken as the longest {@link #KNOWN_COUNTRY_CODES} match, defaulting to a
150	     * two-digit code when none is recognised. It is a derived value; the raw {@code telephone} stays in
151	     * E.164 form.
152	     *
153	     * @return the human-formatted telephone, or the raw {@code telephone} when it is {@code null} or
154	     *         not in E.164 form
155	     */
156	    public String getTelephoneDisplay() {
157	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
158	            return this.telephone;
159	        }
160	        String digits = this.telephone.substring(1);
161	        String countryCode = null;
162	        for (String code : KNOWN_COUNTRY_CODES) {
163	            if (digits.startsWith(code) && digits.length() > code.length()
164	                && (countryCode == null || code.length() > countryCode.length())) {
165	                countryCode = code;
166	            }
167	        }
168	        if (countryCode == null) {
169	            countryCode = digits.substring(0, Math.min(2, digits.length()));
170	        }
171	        String national = digits.substring(countryCode.length());
172	        StringBuilder sb = new StringBuilder("+").append(countryCode);
173	        for (int i = 0; i < national.length(); i += 3) {
174	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
175	        }
176	        return sb.toString();
177	    }
