267	    /**
268	     * The owner's membership points, a non-negative score. It starts at 0 and accumulates: 2 points
269	     * when an email address is present, 1 point when the owner has no namesakes ({@code namesakeCount}
270	     * is zero), 2 points for a household of 3 or more members ({@code householdMemberCount} is at least
271	     * 3), and 3 points for tenure &mdash; the number of whole days from {@code registrationDate} to
272	     * today &mdash; of more than 365 days.
273	     *
274	     * @return the derived membership points (0 or more)
275	     */
276	    public Integer getMembershipPoints() {
277	        int points = 0;
278	        if (this.email != null && !this.email.isBlank()) {
279	            points += 2;
280	        }
281	        if (this.namesakeCount != null && this.namesakeCount == 0) {
282	            points += 1;
283	        }
284	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
285	            points += 2;
286	        }
287	        if (this.registrationDate != null
288	            && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
289	            points += 3;
290	        }
291	        return points;
292	    }
293	
294	    /**
295	     * The owner's membership level, a number from 1 to 4, derived from {@link #getMembershipPoints()}:
296	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more
297	     * points.
298	     *
299	     * @return the derived membership level (1 to 4)
300	     */
301	    public Integer getMembershipLevel() {
302	        int points = getMembershipPoints();
303	        if (points >= 6) {
304	            return 4;
305	        }
306	        if (points >= 4) {
307	            return 3;
308	        }
309	        if (points >= 2) {
310	            return 2;
311	        }
312	        return 1;
313	    }
314	
315	    /**
316	     * The Luhn check digit (0-9) computed over the digits contained in this owner's
317	     * {@code customerCode}. Non-digit characters are ignored; the rightmost digit is doubled.
318	     *
319	     * @return the single Luhn check digit, or {@code null} when there is no customer code
320	     */
321	    public Integer getCheckDigit() {
322	        if (this.customerCode == null) {
323	            return null;
324	        }
325	        int sum = 0;
326	        boolean dbl = true;
327	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
328	            char c = this.customerCode.charAt(i);
329	            if (c < '0' || c > '9') {
330	                continue;
331	            }
332	            int d = c - '0';
333	            if (dbl) {
334	                d *= 2;
335	                if (d > 9) {
336	                    d -= 9;
337	                }
338	            }
339	            sum += d;
340	            dbl = !dbl;
341	        }
342	        return (10 - (sum % 10)) % 10;
343	    }
344	
345	    /**
